```typescript
// src/texteditor/editors/editor.component.ts
import { Component, OnInit } from '@angular/core';
import { TreeListComponent } from '../tree-lists/tree-list.component';

@Component({
  selector: 'app-editor',
  templateUrl: './editor.component.html',
  styleUrls: ['./editor.component.css']
})
export class EditorComponent implements OnInit {
  selectedNodeIndex = null;
  treeLists = [];

  constructor(private treeListComponent: TreeListComponent) {}

  ngOnInit(): void {
    // Initialize with some sample data
    this.treeLists.push(this.treeListComponent);
  }

  onEdit(nodeIndex: number, newNodeName: string) {
    const currentNodes = this.treeLists.map(tree => tree.treeData[nodeIndex]);
    currentNodes[0].name = newNodeName;

    // Update the selected node index
    this.selectedNodeIndex = nodeIndex;
  }

  onDelete(nodeIndex: number) {
    const currentNodes = this.treeLists.map(tree => tree.treeData[nodeIndex]);

    // Remove the node
    currentNodes.forEach((node, i) => {
      this.treeLists[i].treeData.splice(i, 1);
    });
  }

  onCreateNew(nodeIndex: number) {
    const newItem = { id: Date.now(), name: 'New Child' };
    const currentNodes = this.treeLists.map(tree => tree.treeData[nodeIndex]);
    currentNodes[0].children.push(newItem);

    // Update the selected node index
    this.selectedNodeIndex = nodeIndex;
  }

  onSave() {
    console.log('All nodes have been saved.');
  }
}
